using System.Text.Json;
using Meridian.Domain.Messages;
using Meridian.Domain.Rules;

namespace Meridian.Domain.Jobs;

/// <summary>
/// One unit of maintenance work. State changes only through methods on this class,
/// and every change appends a <see cref="JobEvent"/> (AD-5).
/// </summary>
public sealed class Job
{
    private readonly List<Message> _messages = new();
    private readonly List<JobEvent> _events = new();

    /// <summary>Fired rule ids, comma-separated, in the order they first fired; stored as the <c>RuleIds</c> column.</summary>
    private string _ruleIds = string.Empty;

    private Job()
    {
        Reference = string.Empty;
    }

    public Guid Id { get; private set; }

    public string Reference { get; private set; }

    public JobStatus Status { get; private set; }

    public Urgency Urgency { get; private set; }

    public Category Category { get; private set; }

    /// <summary>The property the job is at, once <c>PropertyResolver</c> matched one (AD-13); null when unresolved.</summary>
    public Guid? PropertyId { get; private set; }

    /// <summary>When the job's first message was received (UTC).</summary>
    public DateTime ReceivedAtUtc { get; private set; }

    /// <summary>When the job was opened (UTC).</summary>
    public DateTime CreatedAtUtc { get; private set; }

    /// <summary>Why the job was prepared this way, from the model's proposal (R7). Null until prepared.</summary>
    public string? Explanation { get; private set; }

    /// <summary>English summary of the issue, from the model's proposal. Null until prepared.</summary>
    public string? SummaryEn { get; private set; }

    /// <summary>Language of the tenant's message as reported by the model (e.g. <c>pl</c>). Null until prepared.</summary>
    public string? Language { get; private set; }

    /// <summary>Ids of the emergency rules that fired on this job's messages (see <see cref="EmergencyRuleIds"/>), for the job view.</summary>
    public IReadOnlyList<string> RuleIds =>
        _ruleIds.Length == 0 ? Array.Empty<string>() : _ruleIds.Split(RuleIdSeparator);

    /// <summary>The job's messages: the first plus any follow-ups. A message may also belong to other jobs.</summary>
    public IReadOnlyList<Message> Messages => _messages;

    /// <summary>Messages attached after the first one (R8).</summary>
    public int FollowUpCount => Math.Max(0, _messages.Count - 1);

    /// <summary>True while the job can still take follow-ups: not <see cref="JobStatus.Attended"/> or <see cref="JobStatus.Rejected"/>.</summary>
    public bool IsOpen => Status is not (JobStatus.Attended or JobStatus.Rejected);

    public IReadOnlyList<JobEvent> Events => _events;

    /// <summary>
    /// Creates a job for one issue of a received message (or the message as a whole when there is no usable issue):
    /// status Prepared, category Unsure, urgency Routine. Appends <see cref="EventType.MessageReceived"/> then
    /// <see cref="EventType.JobPrepared"/>. A message can start several jobs.
    /// </summary>
    /// <param name="message">The received message; it becomes the job's first message.</param>
    /// <param name="reference">The job reference, e.g. <c>MER-000001</c>.</param>
    /// <param name="nowUtc">The current time from the application's clock port (AD-9).</param>
    /// <param name="propertyId">The resolved property, or null when it is unresolved (AD-13).</param>
    public static Job CreateFromMessage(Message message, string reference, DateTime nowUtc, Guid? propertyId = null)
    {
        ArgumentNullException.ThrowIfNull(message);
        if (string.IsNullOrWhiteSpace(reference) || !reference.StartsWith(JobReference.Prefix, StringComparison.Ordinal))
        {
            throw new ArgumentException("Reference must start with " + JobReference.Prefix + ".", nameof(reference));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (propertyId == Guid.Empty)
        {
            throw new ArgumentException("Property id must not be empty; pass null when unresolved.", nameof(propertyId));
        }

        var job = new Job
        {
            Id = Guid.NewGuid(),
            Reference = reference,
            Status = JobStatus.Prepared,
            Urgency = Urgency.Routine,
            Category = Category.Unsure,
            ReceivedAtUtc = message.ReceivedAtUtc,
            CreatedAtUtc = nowUtc,
            PropertyId = propertyId,
        };

        job._messages.Add(message);

        job.Append(
            EventType.MessageReceived,
            message.ReceivedAtUtc,
            JobEvent.SystemActor,
            new { messageId = message.Id });

        job.Append(
            EventType.JobPrepared,
            nowUtc,
            JobEvent.SystemActor,
            new
            {
                reference = job.Reference,
                status = job.Status.ToString(),
                urgency = job.Urgency.ToString(),
                category = job.Category.ToString(),
                propertyId = job.PropertyId,
            });

        return job;
    }

    /// <summary>
    /// Attaches a later message to this open job as a follow-up (R8, AD-13): links the message, appends
    /// <see cref="EventType.FollowUpAttached"/> with the message id and this job's reference, then raises urgency to
    /// <paramref name="proposal"/> through <see cref="RaiseUrgency"/> (never lowers it, AD-4).
    /// </summary>
    /// <param name="proposal">The urgency proposed for the follow-up's issue.</param>
    public void AttachFollowUp(Message message, Urgency proposal, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(message);
        if (!Enum.IsDefined(proposal))
        {
            throw new ArgumentOutOfRangeException(nameof(proposal), proposal, "Unknown urgency.");
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (!IsOpen)
        {
            throw new InvalidOperationException($"Job {Reference} is {Status} and cannot take follow-ups.");
        }

        if (_messages.Any(m => m.Id == message.Id))
        {
            throw new InvalidOperationException("The message is already on this job.");
        }

        _messages.Add(message);
        Append(
            EventType.FollowUpAttached,
            nowUtc,
            JobEvent.SystemActor,
            new { messageId = message.Id, reference = Reference, proposedUrgency = proposal.ToString() });
        RaiseUrgency(proposal, FollowUpReason, nowUtc);
    }

    /// <summary>Explanation shown on a job whose message the model found no maintenance problem in.</summary>
    public const string NotMaintenanceExplanation =
        "The AI found no maintenance problem in this message. A person should check it.";

    /// <summary>True once a <see cref="EventType.ModelPrepared"/> or <see cref="EventType.ModelPreparationFailed"/> event exists.</summary>
    public bool HasModelOutcome =>
        _events.Any(e => e.Type is EventType.ModelPrepared or EventType.ModelPreparationFailed);

    /// <summary>
    /// Applies a validated model proposal: sets category, explanation, English summary and language, appends
    /// <see cref="EventType.ModelPrepared"/> with <paramref name="payloadJson"/>, then raises urgency to the
    /// proposal (never lowers it, AD-4).
    /// </summary>
    /// <param name="payloadJson">Event payload with the model metadata (model id, prompt version, latency, raw output, attempts).</param>
    public void ApplyModelPreparation(
        Category category,
        Urgency urgency,
        string explanation,
        string summaryEn,
        string language,
        string payloadJson,
        DateTime nowUtc)
    {
        RequireNoModelOutcome();
        if (string.IsNullOrWhiteSpace(explanation))
        {
            throw new ArgumentException("Explanation is required.", nameof(explanation));
        }

        if (string.IsNullOrWhiteSpace(summaryEn))
        {
            throw new ArgumentException("English summary is required.", nameof(summaryEn));
        }

        if (string.IsNullOrWhiteSpace(language))
        {
            throw new ArgumentException("Language is required.", nameof(language));
        }

        RequireJsonObject(payloadJson, nameof(payloadJson));
        Guards.RequireUtc(nowUtc, nameof(nowUtc));

        Category = category;
        Explanation = explanation;
        SummaryEn = summaryEn;
        Language = language;
        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
        RaiseUrgency(urgency, "model", nowUtc);
    }

    /// <summary>
    /// Records a valid model answer with no issues (not maintenance): the job keeps category Unsure and its urgency,
    /// is flagged for a person with <see cref="NotMaintenanceExplanation"/>, and gets <see cref="EventType.ModelPrepared"/>.
    /// </summary>
    public void ApplyNotMaintenance(string language, string payloadJson, DateTime nowUtc)
    {
        RequireNoModelOutcome();
        if (string.IsNullOrWhiteSpace(language))
        {
            throw new ArgumentException("Language is required.", nameof(language));
        }

        RequireJsonObject(payloadJson, nameof(payloadJson));
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        Category = Category.Unsure;
        Language = language;
        Explanation = NotMaintenanceExplanation;
        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
    }

    /// <summary>
    /// Records that the model gave no usable proposal. The job keeps category Unsure and its urgency (RULE-11).
    /// </summary>
    /// <param name="payloadJson">Event payload with the failure reason, model metadata and validation errors.</param>
    public void RecordModelFailure(string payloadJson, DateTime nowUtc)
    {
        RequireNoModelOutcome();
        RequireJsonObject(payloadJson, nameof(payloadJson));
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        AppendRaw(EventType.ModelPreparationFailed, nowUtc, JobEvent.SystemActor, payloadJson);
    }

    /// <summary>
    /// Records the emergency rules' result for a message (R4): appends <see cref="EventType.RulesApplied"/> listing
    /// each rule id and matched phrase (an empty list when none fired), remembers the fired rule ids, and raises the
    /// job to Emergency with reason <c>rule:&lt;id&gt;</c> of the first hit. Never lowers urgency (AD-4).
    /// </summary>
    /// <param name="hits">The result of <see cref="EmergencyRules.Evaluate"/>.</param>
    public void ApplyRules(IReadOnlyList<RuleHit> hits, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(hits);
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        foreach (var hit in hits)
        {
            if (hit is null || !EmergencyRuleIds.All.Contains(hit.RuleId))
            {
                throw new ArgumentException("Unknown emergency rule.", nameof(hits));
            }
        }

        Append(
            EventType.RulesApplied,
            nowUtc,
            JobEvent.SystemActor,
            new { rules = hits.Select(h => new { id = h.RuleId, matchedPhrase = h.MatchedPhrase }) });

        if (hits.Count == 0)
        {
            return;
        }

        var ruleIds = RuleIds.Concat(hits.Select(h => h.RuleId)).Distinct(StringComparer.Ordinal);
        _ruleIds = string.Join(RuleIdSeparator, ruleIds);
        RaiseUrgency(Urgency.Emergency, RuleReasonPrefix + hits[0].RuleId, nowUtc);
    }

    /// <summary>
    /// Records that a tenant acknowledgement was written to the outbox (R16, AD-8): appends
    /// <see cref="EventType.AcknowledgementSent"/> with the template id and the outbound message id.
    /// </summary>
    /// <param name="outboundId">The id of the stored outbound message.</param>
    /// <param name="templateId">The fixed template it was rendered from, e.g. <c>acknowledgement</c> or <c>gas-safety</c>.</param>
    public void RecordAcknowledgement(Guid outboundId, string templateId, DateTime nowUtc)
    {
        if (outboundId == Guid.Empty)
        {
            throw new ArgumentException("An outbound message id is required.", nameof(outboundId));
        }

        if (string.IsNullOrWhiteSpace(templateId))
        {
            throw new ArgumentException("A template id is required.", nameof(templateId));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        Append(
            EventType.AcknowledgementSent,
            nowUtc,
            JobEvent.SystemActor,
            new { templateId, outboundId });
    }

    /// <summary>
    /// The only way urgency goes down (AD-4): a person sets the urgency to <paramref name="level"/>, higher or lower,
    /// and <see cref="EventType.UrgencySetByPerson"/> records who, from what, to what and why. Called from the review
    /// use case only.
    /// </summary>
    /// <param name="actor">The acting person (e.g. Rachel); never the system actor.</param>
    /// <param name="reason">Why the person changed it; required.</param>
    public void SetUrgencyByPerson(Urgency level, string actor, string reason, DateTime nowUtc)
    {
        if (!Enum.IsDefined(level))
        {
            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
        }

        if (string.IsNullOrWhiteSpace(actor) || string.Equals(actor.Trim(), JobEvent.SystemActor, StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException("A person is required.", nameof(actor));
        }

        if (actor.Length > JobEvent.MaxActorLength)
        {
            throw new ArgumentException($"Actor must be at most {JobEvent.MaxActorLength} characters.", nameof(actor));
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required.", nameof(reason));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        var from = Urgency;
        Urgency = level;
        Append(
            EventType.UrgencySetByPerson,
            nowUtc,
            actor,
            new { from = from.ToString(), to = level.ToString(), reason });
    }

    /// <summary>
    /// The only automatic urgency change (AD-4): raises to <paramref name="level"/> and appends
    /// <see cref="EventType.UrgencyRaised"/>; a value lower than or equal to the current urgency is ignored.
    /// </summary>
    /// <returns>True when the urgency changed.</returns>
    public bool RaiseUrgency(Urgency level, string reason, DateTime nowUtc)
    {
        if (!Enum.IsDefined(level))
        {
            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required.", nameof(reason));
        }

        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (level <= Urgency)
        {
            return false;
        }

        var from = Urgency;
        Urgency = level;
        Append(
            EventType.UrgencyRaised,
            nowUtc,
            JobEvent.SystemActor,
            new { from = from.ToString(), to = level.ToString(), reason });
        return true;
    }

    private const char RuleIdSeparator = ',';
    private const string RuleReasonPrefix = "rule:";
    private const string FollowUpReason = "follow-up";

    private void RequireNoModelOutcome()
    {
        if (HasModelOutcome)
        {
            throw new InvalidOperationException("The model outcome for this job is already recorded.");
        }
    }

    private static void RequireJsonObject(string payloadJson, string paramName)
    {
        try
        {
            using var document = JsonDocument.Parse(payloadJson ?? string.Empty);
            if (document.RootElement.ValueKind != JsonValueKind.Object)
            {
                throw new ArgumentException("Payload must be a JSON object.", paramName);
            }
        }
        catch (JsonException ex)
        {
            throw new ArgumentException("Payload must be valid JSON.", paramName, ex);
        }
    }

    private void Append(EventType type, DateTime occurredAtUtc, string actor, object payload) =>
        AppendRaw(type, occurredAtUtc, actor, JsonSerializer.Serialize(payload));

    private void AppendRaw(EventType type, DateTime occurredAtUtc, string actor, string payloadJson) =>
        _events.Add(new JobEvent(Id, type, occurredAtUtc, actor, payloadJson));
}
namespace Meridian.Domain.Jobs;

/// <summary>Job event types, past tense. Later stories add more.</summary>
public enum EventType
{
    MessageReceived,
    JobPrepared,

    /// <summary>The model's proposal was validated and applied to the job.</summary>
    ModelPrepared,

    /// <summary>The model gave no usable proposal; the job stays Unsure (RULE-11, R10).</summary>
    ModelPreparationFailed,

    /// <summary>The job's urgency went up (AD-4).</summary>
    UrgencyRaised,

    /// <summary>The emergency rules ran on a message (R4); the payload lists the rules that fired, possibly none.</summary>
    RulesApplied,

    /// <summary>A person set the job's urgency, up or down, with a reason (AD-4). The only way urgency goes down.</summary>
    UrgencySetByPerson,

    /// <summary>A later message was attached to this open job as a follow-up (R8, AD-13); it may raise urgency.</summary>
    FollowUpAttached,

    /// <summary>A fixed acknowledgement (or the gas safety message) was written to the outbox for the tenant (R16).</summary>
    AcknowledgementSent,
}
namespace Meridian.Domain.Properties;

/// <summary>
/// A building Meridian manages, e.g. <c>22 Pemberton Road</c> or <c>Alder Court</c>. A name that starts with a
/// house number (<c>22 Pemberton Road</c>) is matched only together with that number (AD-13).
/// </summary>
public sealed class Building
{
    private readonly List<Property> _properties = new();

    private Building()
    {
        Name = string.Empty;
    }

    public Guid Id { get; private set; }

    /// <summary>The building's address as Meridian writes it, e.g. <c>22 Pemberton Road</c>.</summary>
    public string Name { get; private set; }

    public IReadOnlyList<Property> Properties => _properties;

    public static Building Create(Guid id, string name)
    {
        if (id == Guid.Empty)
        {
            throw new ArgumentException("An id is required.", nameof(id));
        }

        if (string.IsNullOrWhiteSpace(name))
        {
            throw new ArgumentException("A building name is required.", nameof(name));
        }

        return new Building { Id = id, Name = name.Trim() };
    }

    /// <summary>Adds the whole building as one property (a house), with no unit.</summary>
    public Property AddWholeBuilding(Guid id) => Add(Property.Create(id, Id, null, Name));

    /// <summary>Adds a flat, e.g. unit <c>4</c> shown as <c>Flat 4, 22 Pemberton Road</c>.</summary>
    /// <param name="name">How the flat is shown; defaults to <c>Flat {unit}, {building}</c>.</param>
    public Property AddFlat(Guid id, string unit, string? name = null)
    {
        if (string.IsNullOrWhiteSpace(unit))
        {
            throw new ArgumentException("A unit is required.", nameof(unit));
        }

        return Add(Property.Create(id, Id, unit.Trim(), name ?? $"Flat {unit.Trim()}, {Name}"));
    }

    private Property Add(Property property)
    {
        if (_properties.Any(p => p.Unit is null) || (property.Unit is null && _properties.Count > 0))
        {
            throw new InvalidOperationException("A whole-building property cannot share a building with flats.");
        }

        if (property.Unit is not null
            && _properties.Any(p => string.Equals(p.Unit, property.Unit, StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException($"Unit {property.Unit} already exists in {Name}.");
        }

        property.SetBuilding(this);
        _properties.Add(property);
        return property;
    }
}
namespace Meridian.Domain.Properties;

/// <summary>One lettable home: a flat in a building, or a whole building (a house) when <see cref="Unit"/> is null.</summary>
public sealed class Property
{
    private Property()
    {
        Name = string.Empty;
    }

    public Guid Id { get; private set; }

    public Guid BuildingId { get; private set; }

    /// <summary>The flat number as Meridian writes it (e.g. <c>4</c>, <c>14b</c>); null for a whole building.</summary>
    public string? Unit { get; private set; }

    /// <summary>How the property is shown, e.g. <c>Flat 4, 22 Pemberton Road</c> or <c>14b Alder Court</c>.</summary>
    public string Name { get; private set; }

    public Building? Building { get; private set; }

    internal static Property Create(Guid id, Guid buildingId, string? unit, string name)
    {
        if (id == Guid.Empty)
        {
            throw new ArgumentException("An id is required.", nameof(id));
        }

        if (string.IsNullOrWhiteSpace(name))
        {
            throw new ArgumentException("A property name is required.", nameof(name));
        }

        return new Property { Id = id, BuildingId = buildingId, Unit = unit, Name = name.Trim() };
    }

    internal void SetBuilding(Building building) => Building = building;
}
namespace Meridian.Domain.Jobs;

/// <summary>The PRD glossary categories, plus Unsure (needs a person).</summary>
public enum Category
{
    Unsure,
    Plumbing,
    Electrical,
    Heating,
    Appliances,
    LocksAndDoors,
    Pest,
    General,
}

using Meridian.Application.Abstractions;
using Meridian.Application.Outbox;
using Meridian.Application.Triage;
using Meridian.Domain.Jobs;
using Meridian.Domain.Messages;
using Meridian.Domain.Rules;

namespace Meridian.Application.Messages;

public sealed record SubmitMessageCommand(string? Sender, string? Text);

/// <summary>One job a message made or was attached to, in the order of the model's issues.</summary>
/// <param name="IsFollowUp">True when the message was attached to an existing job rather than starting it.</param>
public sealed record SubmittedJob(Guid JobId, string Reference, bool IsFollowUp);

public sealed record SubmitMessageResult(
    Guid? MessageId,
    IReadOnlyList<SubmittedJob> Jobs,
    IReadOnlyDictionary<string, string[]> Errors)
{
    public bool Succeeded => Errors.Count == 0;

    public static SubmitMessageResult Invalid(IReadOnlyDictionary<string, string[]> errors) =>
        new(null, Array.Empty<SubmittedJob>(), errors);

    public static SubmitMessageResult Created(Guid messageId, IReadOnlyList<SubmittedJob> jobs) =>
        new(messageId, jobs, new Dictionary<string, string[]>());
}

/// <summary>
/// The intake pipeline (AD-3): stores a pasted message unchanged, evaluates the emergency rules, asks the model
/// (<see cref="PrepareJob"/>), then turns the model's issues into jobs with plain code (AD-13):
/// <list type="number">
/// <item><see cref="PropertyResolver"/> matches each issue's <c>property_text</c>; unresolved or ambiguous → Unsure, property unset.</item>
/// <item><see cref="FollowUpMatcher"/> attaches an issue to an existing open job as a follow-up, which can raise its urgency.</item>
/// <item>Every other issue becomes its own job; one message can make several jobs.</item>
/// </list>
/// The message is committed before the model is called, so a model failure never loses it; when the model fails
/// the message makes one Unsure job, and a valid answer with no issues makes one Unsure job flagged for a person.
/// Every job the message touches gets the rule result (<c>RulesApplied</c>), so a rule emergency applies whatever
/// the model does (RULE-11).
/// In the same second unit of work the sender gets one fixed acknowledgement quoting every job reference the message
/// made or matched (<see cref="AcknowledgeTenant"/>, R16). A crash between the two saves leaves a message with no
/// job; <see cref="RecoverOrphanMessages"/> turns it into one Unsure job and acknowledges it (RULE-11).
/// </summary>
public sealed class SubmitMessage
{
    private readonly IJobRepository _jobs;
    private readonly IPropertyRepository _properties;
    private readonly IUnitOfWork _unitOfWork;
    private readonly IClock _clock;
    private readonly PrepareJob _prepareJob;
    private readonly AcknowledgeTenant _acknowledge;

    public SubmitMessage(
        IJobRepository jobs,
        IPropertyRepository properties,
        IUnitOfWork unitOfWork,
        IClock clock,
        PrepareJob prepareJob,
        AcknowledgeTenant acknowledge)
    {
        _jobs = jobs;
        _properties = properties;
        _unitOfWork = unitOfWork;
        _clock = clock;
        _prepareJob = prepareJob;
        _acknowledge = acknowledge;
    }

    public static IReadOnlyDictionary<string, string[]> Validate(SubmitMessageCommand command)
    {
        var errors = new Dictionary<string, string[]>();
        if (string.IsNullOrWhiteSpace(command.Sender))
        {
            errors["sender"] = new[] { "Sender is required." };
        }

        if (string.IsNullOrWhiteSpace(command.Text))
        {
            errors["text"] = new[] { "Message text is required." };
        }

        return errors;
    }

    public async Task<SubmitMessageResult> ExecuteAsync(SubmitMessageCommand command, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(command);
        var errors = Validate(command);
        if (errors.Count > 0)
        {
            return SubmitMessageResult.Invalid(errors);
        }

        // 1. Store the message, unchanged and once (RULE-9).
        var message = await _unitOfWork.ExecuteAsync(
            _ =>
            {
                var received = Message.Receive(command.Sender!, command.Text!, _clock.UtcNow);
                _jobs.AddMessage(received);
                return Task.FromResult(received);
            },
            cancellationToken);

        // 2. Emergency rules before the model (AD-3); they can only raise urgency (AD-4).
        var hits = EmergencyRules.Evaluate(message.Text, message.ReceivedAtUtc);

        // 3. Model preparation; never throws for a model problem.
        var preparation = await _prepareJob.AskAsync(message, cancellationToken);

        // 4. Jobs, follow-ups and the tenant's acknowledgement (R16). Saved even if the caller has gone away, so the stored message always gets its jobs.
        var jobs = await _unitOfWork.ExecuteAsync(
            ct => MakeJobsAsync(message, hits, preparation, ct),
            CancellationToken.None);

        return SubmitMessageResult.Created(message.Id, jobs);
    }

    private async Task<IReadOnlyList<SubmittedJob>> MakeJobsAsync(
        Message message,
        IReadOnlyList<RuleHit> hits,
        ModelPreparation preparation,
        CancellationToken cancellationToken)
    {
        var response = preparation.Response;
        if (response is null)
        {
            var failed = await NewJobAsync(message, hits, null, cancellationToken);
            PrepareJob.RecordFailure(failed, preparation, _clock.UtcNow);
            _acknowledge.Send(message, hits, new[] { failed }, _clock.UtcNow);
            return new[] { new SubmittedJob(failed.Id, failed.Reference, false) };
        }

        if (response.Issues.Count == 0)
        {
            var flagged = await NewJobAsync(message, hits, null, cancellationToken);
            PrepareJob.RecordNotMaintenance(flagged, preparation, _clock.UtcNow);
            _acknowledge.Send(message, hits, new[] { flagged }, _clock.UtcNow);
            return new[] { new SubmittedJob(flagged.Id, flagged.Reference, false) };
        }

        var resolver = new PropertyResolver(await _properties.ListAsync(cancellationToken));
        var matches = response.Issues.Select(i => resolver.Resolve(i.PropertyText)).ToList();
        var propertyIds = matches.Where(m => m.IsResolved).Select(m => m.Property!.Id).Distinct().ToList();
        var candidates = propertyIds.Count == 0
            ? Array.Empty<Job>()
            : await _jobs.ListOpenAtPropertiesAsync(
                propertyIds,
                message.ReceivedAtUtc - FollowUpMatcher.Window,
                cancellationToken);

        var result = new List<SubmittedJob>();
        var created = new List<Job>();
        var followUps = new Dictionary<Job, Urgency>();
        for (var index = 0; index < response.Issues.Count; index++)
        {
            var issue = response.Issues[index];
            var property = matches[index];
            var category = PrepareJob.CategoryFor(issue, property);

            // Only jobs that existed before this message are candidates: the model's split stands within a message.
            var existing = FollowUpMatcher.Match(candidates, property.Property?.Id, category, message.ReceivedAtUtc);
            if (existing is not null)
            {
                followUps[existing] = followUps.TryGetValue(existing, out var raised) && raised > issue.Urgency
                    ? raised
                    : issue.Urgency;
                result.Add(new SubmittedJob(existing.Id, existing.Reference, true));
                continue;
            }

            var job = await NewJobAsync(message, hits, property.Property?.Id, cancellationToken);
            PrepareJob.RecordIssue(job, preparation, index, property, _clock.UtcNow);
            created.Add(job);
            result.Add(new SubmittedJob(job.Id, job.Reference, false));
        }

        foreach (var (job, urgency) in followUps)
        {
            job.AttachFollowUp(message, urgency, _clock.UtcNow);
            job.ApplyRules(hits, _clock.UtcNow);
        }

        // Two issues attached to the same job are one follow-up.
        var touched = result.DistinctBy(j => j.JobId).ToList();
        var jobsById = followUps.Keys.Concat(created).ToDictionary(j => j.Id);
        _acknowledge.Send(message, hits, touched.Select(j => jobsById[j.JobId]).ToList(), _clock.UtcNow);
        return touched;
    }

    private async Task<Job> NewJobAsync(Message message, IReadOnlyList<RuleHit> hits, Guid? propertyId, CancellationToken cancellationToken)
    {
        var number = await _jobs.NextJobNumberAsync(cancellationToken);
        var job = Job.CreateFromMessage(message, JobReference.FromNumber(number), _clock.UtcNow, propertyId);
        job.ApplyRules(hits, _clock.UtcNow);
        _jobs.Add(job);
        return job;
    }
}
