export interface SubmittedJob {
  jobId: string;
  reference: string;
  /** "created" for a new job, "followUp" when the message was attached to an existing open job. */
  outcome: 'created' | 'followUp';
}

/** A message written to the outbox for a job; sending is simulated in the first version. */
export interface OutboundMessage {
  id: string;
  jobId: string;
  channel: string;
  recipient: string;
  /** The fixed template the body came from, e.g. "acknowledgement" or "gas-safety". */
  templateId: string;
  body: string;
  status: 'Simulated';
  createdAtUtc: string;
}

export interface SubmitMessageResponse {
  messageId: string;
  /** Every job the message made or was attached to. */
  jobs: SubmittedJob[];
}

export interface ProblemDetails {
  title?: string;
  detail?: string;
  status?: number;
  errors?: Record<string, string[]>;
}

export class ApiError extends Error {
  readonly problem: ProblemDetails;

  constructor(problem: ProblemDetails) {
    super(problem.title ?? 'Request failed');
    this.problem = problem;
  }
}

async function readProblem(response: Response): Promise<ProblemDetails> {
  try {
    return (await response.json()) as ProblemDetails;
  } catch {
    return { title: `Request failed (${response.status})`, status: response.status };
  }
}

export async function listJobs(): Promise<JobListItem[]> {
  const response = await fetch('/api/jobs');
  if (!response.ok) {
    throw new ApiError(await readProblem(response));
  }
  return (await response.json()) as JobListItem[];
}

export async function listOutbound(jobId: string): Promise<OutboundMessage[]> {
  const response = await fetch(`/api/jobs/${encodeURIComponent(jobId)}/outbound`);
  if (!response.ok) {
    throw new ApiError(await readProblem(response));
  }
  return (await response.json()) as OutboundMessage[];
}

export async function submitMessage(sender: string, text: string): Promise<SubmitMessageResponse> {
  const response = await fetch('/api/messages', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sender, text }),
  });
  if (!response.ok) {
    throw new ApiError(await readProblem(response));
  }
  return (await response.json()) as SubmitMessageResponse;
}
import { useCallback, useEffect, useState, type FormEvent } from 'react';
import { ApiError, listJobs, submitMessage, type JobListItem, type SubmittedJob } from './api';
import { SentToTenant } from './SentToTenant';

// Stored times are UTC; the UI shows Europe/London (AD-9).
const londonTime = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/London',
  dateStyle: 'medium',
  timeStyle: 'short',
});

function formatReceived(utc: string): string {
  return londonTime.format(new Date(utc));
}

const EXPLANATION_LENGTH = 140;

function shorten(value: string, max: number): string {
  const chars = Array.from(value);
  return chars.length <= max ? value : `${chars.slice(0, max - 1).join('').trimEnd()}…`;
}

function describeSubmitted(jobs: SubmittedJob[]): string {
  const created = jobs.filter((j) => j.outcome === 'created').map((j) => j.reference);
  const followUps = jobs.filter((j) => j.outcome === 'followUp').map((j) => j.reference);
  const parts: string[] = [];
  if (created.length > 0) {
    parts.push(`Added as ${created.join(', ')}`);
  }
  if (followUps.length > 0) {
    parts.push(`Attached as a follow-up to ${followUps.join(', ')}`);
  }
  return parts.join('; ');
}

function errorText(error: unknown): string {
  if (error instanceof ApiError) {
    const fieldErrors = Object.values(error.problem.errors ?? {}).flat();
    return fieldErrors.length > 0 ? fieldErrors.join(' ') : (error.problem.detail ?? error.message);
  }
  return error instanceof Error ? error.message : 'Something went wrong.';
}

export function QueuePage() {
  const [jobs, setJobs] = useState<JobListItem[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [sender, setSender] = useState('');
  const [text, setText] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      setJobs(await listJobs());
      setLoadError(null);
    } catch (error) {
      setLoadError(errorText(error));
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitting(true);
    setSubmitError(null);
    setLastResult(null);
    try {
      const created = await submitMessage(sender, text);
      setLastResult(describeSubmitted(created.jobs));
      setSender('');
      setText('');
      await refresh();
    } catch (error) {
      setSubmitError(errorText(error));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <main>
      <h1>Review queue</h1>

      <section aria-labelledby="paste-heading" className="panel">
        <h2 id="paste-heading">Paste a message</h2>
        <form onSubmit={onSubmit}>
          <label htmlFor="sender">Sender</label>
          <input
            id="sender"
            name="sender"
            value={sender}
            onChange={(e) => setSender(e.target.value)}
